package com.dy.artisan3d.utilimport platform.Foundation.NSURLimport platform.UIKit.UIActivityViewControllerimport platform.UIKit.UIApplicationimport platform.UIKit.UIWindowimport platform.UIKit.popoverPresentationControlleractual fun openExternalUrl(url: String) {    val nsUrl = NSURL.URLWithString(url)    if (nsUrl != null) {        // Yangi API: openURL:options:completionHandler:        UIApplication.sharedApplication.openURL(            url = nsUrl,            options = emptyMap<Any?, Any?>(), // Hech qanday maxsus parametrlar shart emas            completionHandler = null         // Natijani kutish shart emas        )    }}actual fun shareUrl(url: String, title: String) {    val items = listOf(title, NSURL.URLWithString(url)!!)    val activityController = UIActivityViewController(        activityItems = items,        applicationActivities = null    )    // iOS-da UI bilan bog'liq ishlarni asosiy thread-da bajarish shart    val window = UIApplication.sharedApplication.windows.firstOrNull() as? UIWindow    val rootViewController = window?.rootViewController    // iPad uchun crash-ni oldini olish (Popover joylashuvi)    activityController.popoverPresentationController?.let {        it.sourceView = rootViewController?.view    }    rootViewController?.presentViewController(        viewControllerToPresent = activityController,        animated = true,        completion = null    )}